    /*
     * WAVE A1 regression guard. The three tests above use the in-test
     * TestAuthenticator fake. These two go end-to-end through a REAL
     * authenticator implementation configured at the client level, and
     * assert the credential actually reaches the wire. This is the guard
     * for the Elixir bug where a configured authenticator was silently
     * dropped on the way to a secured operation: a client is built WITH an
     * authenticator, the request is issued with no per-call auth (auth =
     * null), so the only way the credential can appear on the outbound
     * request is if the configured client-level authenticator was applied.
     */

    @Test
    @DisplayName(
        "bhvAuthIntegration006 a client-configured Bearer authenticator is applied to the outbound"
            + " request")
    void bhvAuthIntegration006AppliesConfiguredBearerAuthenticator() throws Exception {
      BearerAuthenticator auth = new BearerAuthenticator(ChasmContainer.getBaseUrl(), "secret-jwt");
      TestableApi configured =
          new TestableApi(new DefaultApiClient(), ChasmContainer.getBaseUrl(), auth);
      JsonNode result =
          configured.call(
              "GET",
              "/test/echo",
              new HashMap<>(),
              new HashMap<>(),
              null,
              new String[] {"application/json"},
              "application/json",
              JSON_NODE_TYPE,
              null);
      assertNotNull(result);
      assertEquals("Bearer secret-jwt", result.get("headers").get("authorization").asText());
    }

    @Test
    @DisplayName(
        "bhvAuthIntegration018 a client-configured apiKey-header authenticator is applied to the"
            + " outbound request")
    void bhvAuthIntegration018AppliesConfiguredApiKeyAuthenticator() throws Exception {
      ApiKeyAuthenticator auth =
          new ApiKeyAuthenticator(
              ChasmContainer.getBaseUrl(), "X-API-Key", "secret-key", ApiKeyLocation.HEADER);
      TestableApi configured =
          new TestableApi(new DefaultApiClient(), ChasmContainer.getBaseUrl(), auth);
      JsonNode result =
          configured.call(
              "GET",
              "/test/echo",
              new HashMap<>(),
              new HashMap<>(),
              null,
              new String[] {"application/json"},
              "application/json",
              JSON_NODE_TYPE,
              null);
      assertNotNull(result);
      assertEquals("secret-key", result.get("headers").get("x-api-key").asText());
    }

    /*
     * WAVE A2 — security:[] suppression guard. An operation declared
     * `security: []` opts out of all auth. Its generated method passes the
     * NO_AUTH sentinel (not null) as the auth argument; BaseApi must then
     * NOT fall back to the client-level authenticator. Without this, a
     * configured client credential would leak onto an unauthenticated
     * operation (e.g. a testEcho* op that reflects the request back). These
     * tests drive a configured client and assert the credential is absent
     * from the outbound request when the sentinel is supplied — the mirror
     * image of the A1 fallback guard above.
     */

    @Test
    @DisplayName(
        "bhvAuthIntegration015 NO_AUTH sentinel suppresses the client-level authenticator's header,"
            + " query, and cookie")
    void bhvAuthIntegration015NoAuthSentinelSuppressesClientAuthenticator() throws ApiException {
      var client = new CapturingApiClient();
      var clientAuth =
          new TestAuthenticator(
              Map.of("X-Client-Auth", "client-level-token"),
              Map.of("api_key", "client-key"),
              Map.of("session", "client-cookie"));
      var testApi = new TestableApi(client, "http://localhost", clientAuth);
      testApi.call(
          "GET",
          "/test/echo",
          new HashMap<>(),
          new HashMap<>(),
          null,
          new String[] {"application/json"},
          "application/json",
          null,
          TestableApi.NO_AUTH_SENTINEL);
      // The configured authenticator must NOT reach the wire for an
      // explicitly unauthenticated (security:[]) operation.
      assertFalse(
          client.capturedHeaders.containsKey("X-Client-Auth"),
          "client auth header must be suppressed for a security:[] operation");
      assertFalse(
          client.capturedHeaders.containsKey("Cookie"),
          "client auth cookie must be suppressed for a security:[] operation");
      assertFalse(
          client.capturedUrl.contains("api_key="),
          "client auth query param must be suppressed for a security:[] operation, got: "
              + client.capturedUrl);
    }

    @Test
    @DisplayName(
        "bhvAuthIntegration016 a security:[] operation sends no credential even though the client"
            + " is configured (end-to-end)")
    void bhvAuthIntegration016SecurityNoneOperationSendsNoCredentialEndToEnd() {
      // Build a client WITH a real authenticator that injects a header, a
      // query param, AND a cookie, then invoke the generated security:[]
      // operation getInventory. The operation passes NO_AUTH, so none of
      // the three credential channels may appear on the outbound request.
      var captured = new HashMap<String, String>();
      var capturingClient =
          new CapturingApiClient() {
            @Override
            public ApiHttpResponse sendRequest(
                String method, String url, Map<String, String> headers, @Nullable Object body) {
              captured.putAll(headers);
              this.capturedUrl = url;
              return new ApiHttpResponse(200, "{}", Map.of("Content-Type", "application/json"));
            }
          };
      var clientAuth =
          new TestAuthenticator(
              Map.of("Authorization", "Bearer leaked-secret"),
              Map.of("api_key", "leaked-key"),
              Map.of("session", "leaked-cookie"));
      var config = new Configuration("http://localhost", Map.of());
      var storeApi = new StoreApi(capturingClient, config, clientAuth);
      try {
        storeApi.getInventory();
      } catch (Exception ignored) {
        // Response shape is irrelevant; we only assert outbound headers.
      }
      assertFalse(
          captured.containsKey("Authorization"),
          "Authorization must be absent for the security:[] getInventory operation");
      assertFalse(
          captured.containsKey("Cookie"),
          "auth cookie must be absent for the security:[] getInventory operation");
      assertFalse(
          capturingClient.capturedUrl.contains("api_key="),
          "api-key query param must be absent for getInventory, got: "
              + capturingClient.capturedUrl);
    }

    @Test
    @DisplayName(
        "bhvAuthIntegration012 an inherited-security operation applies the configured client"
            + " authenticator (end-to-end)")
    void bhvAuthIntegration012InheritedSecurityOperationAppliesClientAuthenticatorEndToEnd() {
      // getPetById declares no security of its own, so it inherits the
      // global requirement. This generator strips the inherited auth
      // methods off such an operation, so the generated method passes null
      // (not NO_AUTH) and BaseApi falls back to the client-level
      // authenticator. The configured client credential MUST reach the
      // wire — the regression that silently dropped auth on every
      // inherited-security operation.
      var captured = new HashMap<String, String>();
      var capturingClient =
          new CapturingApiClient() {
            @Override
            public ApiHttpResponse sendRequest(
                String method, String url, Map<String, String> headers, @Nullable Object body) {
              captured.putAll(headers);
              this.capturedUrl = url;
              return new ApiHttpResponse(200, "{}", Map.of("Content-Type", "application/json"));
            }
          };
      var clientAuth =
          new TestAuthenticator(
              Map.of("Authorization", "Bearer client-secret"), Map.of(), Map.of());
      var config = new Configuration("http://localhost", Map.of());
      var petApi = new PetApi(capturingClient, config, clientAuth);
      try {
        petApi.getPetById(1L);
      } catch (Exception ignored) {
        // Response shape is irrelevant; we only assert outbound headers.
      }
      assertEquals(
          "Bearer client-secret",
          captured.get("Authorization"),
          "the client authenticator must be applied to the inherited-security getPetById"
              + " operation");
    }

