    @Test
    @DisplayName("bhvSerializationWire012 form-urlencoded body encodes space as + not %20")
    void bhvSerializationWire012FormUrlencodedBodyEncodesSpaceAsPlus() throws ApiException {
      // form-urlencoded-space-plus-vs-pct20: application/x-www-form-urlencoded
      // is defined by the WHATWG/HTML form-encoding standard, which mandates
      // '+' for a space (not RFC-3986 '%20'). URLEncoder.encode emits '+',
      // keeping the wire bytes identical across all SDKs.
      var client = new CapturingApiClient();
      var testApi = new TestableApi(client, "http://localhost");
      Map<String, String> formParams = new java.util.LinkedHashMap<>();
      formParams.put("full name", "Ada Lovelace");
      testApi.call(
          "POST",
          "/test/echo",
          new HashMap<>(),
          new HashMap<>(),
          formParams,
          new String[] {"application/json"},
          "application/x-www-form-urlencoded",
          null,
          null);
      assertNotNull(client.capturedBody);
      String wire = client.capturedBody.toString();
      assertEquals("full+name=Ada+Lovelace", wire);
      assertFalse(wire.contains("%20"));
    }

    @Test
    @DisplayName("bhvSerializationWire057 form-urlencoded body keeps ~ literal and escapes *")
    void bhvSerializationWire057FormUrlencodedBodyKeepsOnlyTheUnreservedSetLiteral()
        throws ApiException {
      var client = new CapturingApiClient();
      var testApi = new TestableApi(client, "http://localhost");
      Map<String, String> formParams = new java.util.LinkedHashMap<>();
      formParams.put("k~*", "a~b*c!d'e(f)g h");
      testApi.call(
          "POST",
          "/test/echo",
          new HashMap<>(),
          new HashMap<>(),
          formParams,
          new String[] {"application/json"},
          "application/x-www-form-urlencoded",
          null,
          null);
      assertEquals("k~%2A=a~b%2Ac%21d%27e%28f%29g+h", client.capturedBody);
    }

